/**
 * Interactive mode: Prompt for resolution of each drifted component.
 */
async function executeInteractiveMode(context, drift) {
    if (drift.name) {
        await handleNameDriftInteractive(context, drift.name);
    }
    if (drift.persona) {
        await handlePersonaDriftInteractive(context, drift.persona);
    }
    if (drift.model) {
        await handleModelDriftInteractive(context, drift.model);
    }
    writeSuccess('\n✅ Sync complete.');
}
/**
 * Handle name drift interactively.
 */
async function handleNameDriftInteractive(context, drift) {
    showNameDiff(drift.serverName, drift.localName);
    const answer = await safePrompt([
        {
            type: 'list',
            name: 'action',
            message: 'What would you like to do with the name?',
            choices: [
                { name: '📤 Push local to server', value: 'push' },
                { name: '📥 Pull server to local', value: 'pull' },
                { name: '⏭️  Skip', value: 'skip' },
            ],
        },
    ]);
    if (!answer || answer.action === 'skip') {
        writeInfo('Skipped name sync.');
        return;
    }
    if (answer.action === 'push') {
        writeProgress('📤 Pushing name to server...');
        try {
            if (await agentHandler.pushName(context, drift.localName)) {
                writeSuccess(`✅ Agent name updated to "${drift.localName}"`);
            }
            else {
                console.error('❌ Failed to update name');
            }
        }
        catch (error) {
            console.error('❌ Failed to update name:', error.message);
        }
    }
    else if (answer.action === 'pull' && drift.serverName) {
        writeProgress('📥 Updating name in code...');
        if (agentHandler.pullName(drift.serverName)) {
            writeSuccess('✅ Name updated in src/index.ts');
        }
        else {
            console.error('❌ Failed to update name in code.');
        }
    }
}
