/**
 * Run sync check during compile flow.
 * By default, warns about drift but continues compilation (non-blocking).
 */
export async function runSyncCheck(apiKey, agentId) {
    const drift = await agentHandler.checkDrift(apiKey, agentId);
    if (!agentHandler.hasDrift(drift)) {
        return true;
    }
    // Warn about drift but continue compilation
    console.log('\n⚠️  Drift detected between local code and server.');
    if (drift.name) {
        writeInfo(`   Name: local "${drift.name.localName}" ≠ server "${drift.name.serverName || '(empty)'}"`);
    }
    if (drift.persona) {
        writeInfo('   Persona: local and server versions differ');
    }
    if (drift.model) {
        writeInfo(`   Model: local "${drift.model.localModel}" ≠ server "${drift.model.serverModel || '(empty)'}"`);
    }
    console.log();
    writeInfo('💡 To resolve drift:');
    writeInfo('   lua sync --push    Push local changes to server');
    writeInfo('   lua sync --accept  Pull server changes to local');
    writeInfo('   lua sync           Interactive resolution');
    console.log();
    return true;
}
